const { execSync } = require('child_process');
const fs = require('fs');
const https = require('https');

const DIR = '/home/ubuntu/job-scripts';
const BASE = 'https://raw.githubusercontent.com/harshayelamati/ai-automation-system/main/scripts';

// Helper: download a file
function download(url, dest) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(dest);
    https.get(url, res => {
      res.pipe(file);
      file.on('finish', () => { file.close(); resolve(); });
    }).on('error', reject);
  });
}

// 1. Create directory
execSync(`mkdir -p ${DIR}`);

// 2. Download scripts
await download(`${BASE}/build_resume_dynamic.js`, `${DIR}/build_resume_dynamic.js`);
await download(`${BASE}/resume_base_data.js`,     `${DIR}/resume_base_data.js`);

// 3. Create package.json so npm install works
fs.writeFileSync(`${DIR}/package.json`, JSON.stringify({ name: 'job-scripts', version: '1.0.0', dependencies: { docx: '^8.0.0' } }, null, 2));

// 4. npm install
execSync(`cd ${DIR} && npm install`, { timeout: 120000 });

// 5. Verify
const files = fs.readdirSync(DIR);
const docxOk = fs.existsSync(`${DIR}/node_modules/docx`);

return [{ json: {
  status: 'SUCCESS',
  directory: DIR,
  files,
  docx_installed: docxOk,
  message: docxOk ? '✅ All set. Resume DOCX generation ready.' : '⚠️ npm install may have failed — check manually.'
}}];
